from lib import *
FV="Portions de fruits et légumes"
def fv(n): return (FV,f"Portions de fruits et légumes par portion : {n}")
recs=[
R(6704624,"Parmigiana d'aubergines",
"Oui, vous pouvez préparer des aubergines croustillantes et fondantes de fromage que toute la famille adorera, avec des céréales complètes et sans friture ! Servez avec une salade verte et des pâtes de blé entier pour un repas complet. Pour une option pauvre en glucides, utilisez des nouilles de courgette ou de la courge spaghetti à la place des pâtes.",
"10",None,
["1/2 tasse de farine","1/2 cuillère à café de basilic séché","1/4 cuillère à café de poivre noir","3 blancs d'œufs (battus)","1 tasse de chapelure panko de blé entier","1/4 tasse de parmesan (fraîchement râpé)","1 aubergine moyenne (environ 1 lb) (coupée en tranches de 1/2 pouce d'épaisseur)","1 cuillère à soupe d'huile d'olive","1 vaporisation d'enduit de cuisson antiadhésif en aérosol","1 pot (24 oz) de sauce marinara réduite en sodium","1/4 tasse de mozzarella partiellement écrémée, râpée"],
["Préchauffez le four à 350 °F.","Dans un bol moyen, mélangez la farine, le basilic et le poivre. Dans un autre bol moyen, mélangez la chapelure et le parmesan. Dans un troisième bol moyen, mettez les blancs d'œufs.","Trempez les deux faces des tranches d'aubergine dans la farine, puis dans les œufs, puis dans la chapelure, en les enrobant bien. Réservez.","Mettez l'huile et l'enduit de cuisson dans une grande poêle antiadhésive à feu moyen-vif. Faites cuire l'aubergine par lots, environ 2 minutes de chaque côté. Utilisez un peu d'enduit de cuisson supplémentaire pour chaque lot.","Disposez les tranches d'aubergine au fond d'un plat de cuisson de 13 x 9 pouces. Versez la sauce pour pâtes sur l'aubergine afin de couvrir toutes les tranches. Saupoudrez de mozzarella et faites cuire au four 30 minutes, jusqu'à ce que le fromage soit fondu et légèrement doré."]),
R(6736641,"Salade de pois chiches - recette rapide",
"Les haricots et les légumineuses comptent parmi les glucides les plus sains que vous puissiez manger si vous avez du diabète. La plupart des gens disent aimer les haricots, mais ne savent pas trop comment en consommer davantage. Essayez cette délicieuse salade riche en fibres, en protéines et en saveur !",
"16",None,
["1 boîte de pois chiches (16 onces, rincés et égouttés)","2 cuillères à soupe de mayonnaise légère","1/2 citron (pressé)","1/4 tasse de poivron rouge (en dés)","1/4 tasse de céleri (en dés)","1 pincée de poivre noir moulu","1 pincée de piment de Cayenne (si vous préférez moins épicé, utilisez du paprika)","2 concombres (pelés et coupés en rondelles)"],
["Dans un saladier moyen, mélangez tous les ingrédients de la salade.","Dans un petit bol, fouettez les ingrédients de la vinaigrette. Versez sur le mélange de haricots et mélangez pour bien enrober."]),
R(6871291,"Pizza avec salade grecque",
"Vous pouvez servir ceci avec une sauce tzatziki maison. Pour la préparer, râpez 1 petit concombre et 1 gousse d'ail dans 1/2 tasse de yogourt grec nature sans gras et mélangez.",
"4",None,
["1 tasse d'épinards (hachés)","1 cuillère à soupe d'olives Kalamata (dénoyautées, hachées)","1/2 tasse d'oignon rouge (émincé finement)","4 cuillères à café de vinaigre balsamique","1 cuillère à soupe d'huile d'olive","2 pitas de blé entier (sans poche)","1 vaporisation d'enduit de cuisson antiadhésif en aérosol","1/2 tasse de cœurs d'artichaut (égouttés et rincés, hachés)","1 tasse de poitrine de poulet cuite (coupée en cubes)","1/3 tasse de fromage feta (réduit en gras)","1 cuillère à café d'origan séché"],
["Préchauffez le four à 375 degrés F. Enduisez une plaque de cuisson d'enduit de cuisson. Réservez.","Badigeonnez chaque pita d'une partie de l'huile d'olive, en utilisant la cuillère à soupe entière.","Arrosez chaque pita de 2 cuillères à café de vinaigre balsamique.","Garnissez chaque pita de 1/4 tasse d'oignon rouge, 1/2 cuillère à soupe d'olives, 1/2 tasse d'épinards, 1/4 tasse d'artichauts, 1/2 tasse de poulet et la moitié du fromage feta.","Saupoudrez le dessus de chaque pita d'origan séché. Placez sur la plaque de cuisson préparée.","Faites cuire au four 15 minutes. Coupez en quartiers et servez."]),
R(6917425,"Salade de thon à l'asiatique",
"Cette salade de thon à l'asiatique est parfaite pour les amateurs de bonne cuisine qui cherchent un plat principal sain avec une touche asiatique !",
"4","1.5 tasse de salade avec un peu moins de 4 oz (113 grammes) de poisson.",
["2 cuillères à soupe de sauce soya faible en sodium ou réduite en sodium","2 1/2 cuillères à soupe de succédané de cassonade faible en calories","1 cuillère à café de sauce piquante asiatique (Sriracha, facultatif)","1/2 cuillère à café de poivre noir","1 vaporisation d'enduit de cuisson antiadhésif en aérosol","1 lb de thon blanc frais","1 lb d'asperges (parées)","1 cuillère à café de graines de sésame","6 tasses de laitue printanière mélangée (lavée et séchée, ou essorée dans une essoreuse à salade)","1 gros poivron rouge (coupé en julienne)","1 concombre moyen (épépiné et coupé en julienne)","1/4 tasse de vinaigre de vin de riz","1 cuillère à soupe d'huile de sésame grillé"],
["Préchauffez un gril d'intérieur ou d'extérieur.","Dans un petit bol, fouettez ensemble la sauce soya, le succédané de cassonade, la sauce piquante (facultatif) et le poivre noir. Réservez.","Vaporisez le gril d'intérieur d'enduit de cuisson. Si vous utilisez un gril d'extérieur, assurez-vous que les grilles sont propres et légèrement huilées.","Badigeonnez le thon et les asperges de la marinade à la sauce soya. Placez-les sur le gril. Faites griller le thon 3 minutes de chaque côté. Faites griller les asperges en les retournant fréquemment, jusqu'à ce qu'elles commencent à ramollir (environ 6 à 8 minutes). Retirez le thon et les asperges du gril, saupoudrez de graines de sésame et laissez refroidir. Le thon doit être légèrement rosé au centre, mais pas cru.","Mélangez la laitue, le poivron rouge et le concombre dans un saladier.","Dans un petit bol, fouettez les ingrédients de la vinaigrette. Versez sur la salade et mélangez délicatement pour bien enrober. Répartissez la salade également entre quatre assiettes.","Une fois que le thon et les asperges ont refroidi à température ambiante ou sont légèrement tièdes, tranchez le thon et répartissez-le également entre les quatre salades (un peu moins de 4 oz ou 115 grammes de thon par salade). Déposez-le délicatement sur la salade.","Coupez les asperges en deux et disposez-les autour du bord de la salade."]),
R(7002183,"Poppadoms garnis de canard épicé",
"Ils ont l'air impressionnants, mais sont en fait très simples à préparer. Les mini poppadoms sont idéaux pour une réception avec boissons.",
"40","17 g",
["2 magrets de canard, peau et gras retirés (poids 400 g)","2 cuillères à café de cinq-épices chinois","1 cuillère à soupe d'huile de colza","40 mini poppadoms","1 morceau de concombre de 6 cm, épépiné et finement haché","2 cuillères à soupe de coriandre fraîche, grossièrement hachée","4 oignons verts, finement émincés","4 cuillères à soupe de chutney de mangue"],
["Placez les magrets de canard dans un plat non métallique et frottez-les de poudre de 5 épices chinois. Laissez mariner au moins 10 minutes. Coupez le canard en petits morceaux.","Faites chauffer l'huile dans une poêle antiadhésive. Ajoutez le canard et faites-le frire 2 à 3 minutes, jusqu'à ce qu'il soit croustillant et doré.","Mélangez le concombre, la coriandre et les oignons verts, et déposez-en un peu sur chaque poppadom.","Ajoutez à la cuillère un peu de chutney de mangue et garnissez chaque poppadom d'un morceau de canard."],
["Vous pouvez utiliser de la poitrine de poulet ou du bifteck maigre à la place du canard.","Pour une version végétalienne, remplacez le canard par de petits cubes de tofu.",fv(0)]),
R(7002703,"Salade croustillante au saumon",
"Les pommes de terre, les tomates et le saumon se combinent pour créer cette salade copieuse.",
"2","338 g",
["250 g de pommes de terre nouvelles","8 tomates cerises, coupées en deux","90 g de feuilles de salade mélangées","2 filets de saumon sans peau (environ 100 g chacun)","1 cuillère à soupe de poivre noir moulu grossièrement","le zeste râpé et le jus de 1 orange","1 cuillère à soupe de moutarde à l'ancienne"],
["Faites bouillir les pommes de terre 10 à 15 minutes jusqu'à ce qu'elles soient tendres, puis rafraîchissez-les à l'eau froide, laissez-les refroidir un peu et tranchez-les.","Mélangez les tranches de pomme de terre et les tomates et répartissez-les dans 2 plats de service. Empilez les feuilles de salade par-dessus et réservez.","Enrobez un côté de chaque filet de saumon de poivre.","Faites chauffer une poêle antiadhésive ou une plaque à griller jusqu'à ce qu'elle soit bien chaude. Placez le saumon côté poivre vers le bas et faites cuire 3 à 4 minutes, puis retournez-le et faites cuire encore 3 à 4 minutes, jusqu'à ce qu'il soit bien cuit à cœur.","Déposez le saumon sur les feuilles de salade, mélangez le zeste et le jus d'orange avec la moutarde, arrosez-en la salade et servez."],
["Cette salade est délicieuse avec d'autres poissons, comme des filets de maquereau, du thon frais ou des grosses crevettes. Vous pouvez aussi utiliser de la poitrine de poulet tranchée finement.","Pour une alternative végétalienne, essayez des lanières de tofu à la place du saumon. Faites-les simplement frire dans une poêle antiadhésive jusqu'à ce qu'elles soient croustillantes, puis mélangez-les avec un peu d'huile de sésame, de sauce soya et de cinq-épices chinois.",fv(1)]),
R(7006166,"Pizza aux pommes de terre",
"Une garniture de pizza végétarienne différente du traditionnel fromage et tomate.",
"4","171 g",
[("Pour la pâte","100 g de farine de blé entier nature"),("Pour la pâte","150 g de farine nature"),("Pour la pâte","1 pincée de sel"),("Pour la pâte","1 sachet de 7 g de levure à mélange facile"),("Pour la pâte","1 cuillère à soupe de lait demi-écrémé"),("Pour la pâte","1 cuillère à soupe d'huile d'olive"),("Pour la garniture","250 g de pommes de terre à chair ferme, finement tranchées"),("Pour la garniture","1 cuillère à soupe d'huile d'olive"),("Pour la garniture","1 oignon, tranché"),("Pour la garniture","les feuilles de 1 brin de romarin"),("Pour la garniture","1 cuillère à soupe de thym frais"),("Pour la garniture","4 cuillères à soupe de crème fraîche à 15 % de matières grasses"),("Pour la garniture","poivre noir fraîchement moulu")],
["Préchauffez le four à 220 °C/thermostat 7.","Mettez les farines et la levure dans un grand bol. Mélangez le lait, l'huile et 125 ml d'eau tiède, versez sur la farine et travaillez pour former une pâte souple.","Renversez sur une surface légèrement farinée et pétrissez 5 à 6 minutes, jusqu'à ce que la pâte soit lisse. Placez dans un bol légèrement huilé, couvrez d'un linge humide et laissez reposer dans un endroit chaud 30 minutes.","Pendant ce temps, faites mijoter les pommes de terre dans de l'eau légèrement salée 5 minutes. Égouttez.","Faites chauffer l'huile dans une poêle antiadhésive et faites revenir l'oignon 3 à 4 minutes, jusqu'à ce qu'il soit ramolli.","Coupez la pâte en deux et façonnez chaque morceau en un cercle de 23 cm, d'environ 1/2 à 1 cm d'épaisseur, puis placez-les sur une plaque de cuisson épaisse.","Préparez la garniture en ajoutant le romarin, le thym, la crème fraîche et le poivre aux pommes de terre, puis répartissez sur les fonds de pizza. Laissez reposer 5 minutes, puis faites cuire au four 15 à 20 minutes, jusqu'à ce que ce soit croustillant et doré."],
["Parsemez la pizza cuite d'une poignée de feuilles de roquette fraîche et d'un filet de vinaigre balsamique, ou de quelques tomates cerises hachées et de deux oignons verts hachés.","Essayez d'étaler 1 cuillère à café de pâte de cari sur le fond de pizza avant la cuisson.",fv(0)]),
R(7006687,"Salade de bœuf à la vietnamienne",
"Une salade consistante mais légère, avec du bœuf tendre et des germes de soja.",
"6","255 g",
["350 g de bœuf maigre, coupé en lanières","1/2 cuillère à café de flocons de piment","2 gousses d'ail, écrasées","4 cm de gingembre frais, finement haché","1 poivron rouge, tranché","150 g de mini-épis de maïs, coupés en deux dans le sens de la longueur","300 g de germes de soja","6 oignons verts, coupés en morceaux de 1 cm",("Pour la vinaigrette","1 morceau de concombre de 10 cm, finement haché"),("Pour la vinaigrette","25 g de coriandre, grossièrement hachée"),("Pour la vinaigrette","le jus de 1 lime"),("Pour la vinaigrette","2 cuillères à café de sauce soya réduite en sel"),("Pour la vinaigrette","300 g de nouilles de riz fraîches précuites")],
["Mettez l'huile dans une poêle. Ajoutez le bœuf et faites-le cuire 4 à 5 minutes à feu vif en remuant régulièrement. Incorporez les flocons de piment, l'ail et le gingembre.","Ajoutez ensuite le poivron rouge en remuant 2 à 3 minutes, puis les mini-épis de maïs. Remuez 1 minute.","Ajoutez les germes de soja et les oignons verts, mélangez bien 1 minute et retirez du feu. Laissez refroidir.","Pour la vinaigrette, mettez le concombre, la coriandre, le jus de lime et la sauce soya dans un petit bol.","Ajoutez la vinaigrette aux nouilles et mélangez bien. Ajoutez ensuite le mélange de bœuf refroidi, mélangez et servez."],
[fv(1)]),
R(7007009,"Poulet balti",
"Un plat balti parfumé, savoureux et réconfortant.",
"2","467 g",
["1 cuillère à café d'huile de colza","1 oignon, haché","2 poitrines de poulet sans peau, coupées en cubes","1 poivron vert, haché","2 carottes, hachées","1 branche de céleri","4 gousses d'ail, écrasées","2 à 3 cuillères à café bombées de poudre de cari","1 cuillère à café bombée de garam masala","1 piment vert, coupé en rondelles","1 boîte de 400 g de tomates hachées","1 cuillère à soupe de concentré de tomate","25 g de coriandre fraîche, hachée"],
["Mettez l'huile dans une poêle, puis l'oignon, et faites cuire 3 à 4 minutes jusqu'à ce qu'il soit ramolli. Ajoutez le poulet et faites cuire 2 à 3 minutes.","Ajoutez le poivron, la carotte et le céleri, et faites cuire 3 à 4 minutes en remuant régulièrement.","Ajoutez l'ail, la poudre de cari et le garam masala, et remuez bien pour enrober le tout d'épices.","Ajoutez le piment, les tomates et le concentré de tomate, et portez à léger frémissement.","Couvrez et laissez mijoter 12 à 14 minutes, jusqu'à ce que la carotte soit tendre. Incorporez la coriandre et servez."],
["Nous avons utilisé de la poudre de cari : contrairement à la pâte de cari, elle ne contient ni sel ni gras ajouté.","Vous pouvez utiliser du porc maigre ou des cubes d'agneau pour ce plat. Pour une version végétarienne/végétalienne, remplacez le poulet par une boîte de pois chiches ou de haricots mélangés.",fv(3)]),
R(7007691,"Frittata aux asperges",
"Un déjeuner super savoureux qui ne demande que quatre ingrédients.",
"2","237 g",
["1 botte de 250 g d'asperges fraîches (185 g une fois parées)","1/2 botte (60 g) d'oignons verts, hachés","3 œufs moyens, battus","1/2 sac moyen (p. ex. 150 g) de feuilles d'épinards frais","1 vaporisation d'huile en aérosol à 1 calorie (environ 7 jets d'huile)","poivre noir au goût"],
["Cassez les bouts des asperges à l'endroit où elles se brisent naturellement, puis coupez-les en assez gros morceaux.","Hachez finement les oignons verts.","Battez les œufs ensemble, puis assaisonnez de poivre noir au goût.","Vaporisez une petite poêle d'huile en aérosol à 1 calorie et placez-la à feu moyen.","Faites revenir les oignons verts et les asperges quelques minutes, jusqu'à ce qu'ils commencent à ramollir.","Ajoutez les épinards et faites cuire encore quelques minutes, jusqu'à ce que les épinards soient tombés.","Versez les œufs battus dans la poêle, répartissez les asperges uniformément dans le mélange et faites cuire environ 5 minutes, jusqu'à ce que les bords commencent à dorer.","Retirez la poêle de la plaque de cuisson et placez-la sous un gril chaud jusqu'à ce que la frittata commence à dorer."],
[fv(2)]),
R(7007930,"Gâteau aux carottes",
"Cette version plus saine est facile à préparer. Nous l'avons coupé en 18 parts, mais vous pouvez facilement le diviser en 24 petits carrés pour une fête.",
"18","76 g",
["300 g de farine de blé entier","1 cuillère à café de levure chimique","2 cuillères à café d'épices mélangées","3 œufs, battus","1 banane, écrasée","3 cuillères à soupe d'édulcorant granulé","50 ml d'huile de colza + 2 cuillères à café pour huiler le moule","50 g de raisins secs sultanines","400 g de carottes",("Pour le glaçage","250 g de quark sans gras (fromage à la crème)"),("Pour le glaçage","1 cuillère à soupe d'édulcorant granulé"),("Pour le glaçage","le zeste de 1 orange"),("Pour le glaçage","20 g de morceaux de noix")],
["Réglez le four à 180 °C/thermostat 4 et graissez légèrement un moule à gâteau de 20 cm x 25 cm avec l'huile de colza.","Dans un bol, mélangez la farine, la levure chimique et les épices.","Dans un autre bol, mettez les œufs et la banane et battez bien. Incorporez l'édulcorant et l'huile.","Incorporez graduellement les ingrédients secs au mélange de banane, d'œufs et d'huile, puis incorporez les raisins secs et les carottes.","Versez le mélange dans le moule et faites cuire au four 25 à 30 minutes, puis sortez-le du four et laissez refroidir sur une grille.","Lorsque le gâteau est refroidi, couvrez-le de quark sucré et garnissez de zeste d'orange et de morceaux de noix."],
["Assurez-vous que le gâteau est complètement refroidi avant de le garnir, sinon le fromage à la crème fondra.","Essayez de le couper en petits carrés avant de le garnir, puis déposez une noisette de fromage à la crème sucré à la poche sur chaque carré et saupoudrez de zeste d'orange et d'un morceau de noix.","Vous pouvez utiliser de la cannelle à la place des épices mélangées ou essayer d'autres noix, comme des noisettes ou des amandes."]),
R(7011229,"Ragoût de courge butternut et de haricots borlotti",
"Un plat d'hiver coloré que vous pouvez cuisiner dans une seule poêle.",
"6","454 g",
["1 cuillère à café d'huile de colza","2 oignons rouges, hachés","1 courge butternut moyenne, épépinée, pelée et coupée en cubes","1 poivron vert, haché","1 cube de bouillon de légumes dissous dans 500 ml d'eau","2 boîtes de 400 g de tomates","50 g de lentilles rouges sèches","1 cuillère à café bombée d'origan séché","1 bonne pincée de flocons de piment","4 gousses d'ail, écrasées","2 boîtes de 400 g de haricots borlotti, égouttés","1 bon tour de moulin de poivre noir","1 cuillère à soupe de persil haché, pour garnir"],
["Faites chauffer l'huile dans une casserole et ajoutez les oignons, la courge et le poivron vert. Remuez régulièrement 5 minutes, jusqu'à ce qu'ils commencent à dorer.","Ajoutez le bouillon, les tomates, les lentilles rouges, l'origan, le piment et l'ail. Portez à ébullition, réduisez le feu, couvrez et laissez mijoter 10 minutes.","Ajoutez les haricots et faites chauffer encore 10 minutes, en vérifiant que la courge est bien cuite (tendre). Servez avec un bon tour de moulin de poivre noir et un peu de persil."],
["Idéal avec de la citrouille à la place de la courge butternut.","Tous les haricots conviennent : vous pouvez utiliser deux types différents ou des boîtes de haricots mélangés.","Essayez de farcir des moitiés de poivron avec ce ragoût, de saupoudrer d'un peu de fromage et de faire cuire au four à 180°/thermostat 4 pendant 15 minutes, jusqu'à ce que le poivron soit tendre et le fromage doré.","Instructions de congélation : peut être congelé une fois cuit. Décongelez ensuite au réfrigérateur et réchauffez au micro-ondes ou sur la cuisinière jusqu'à ce que ce soit bien chaud à cœur.",fv(5)]),
R(7013544,"Gâteau aux pommes et à la cannelle",
"Un délicieux dessert préparé avec de la farine de blé entier",
"8","159 g",
["100 g de farine de blé entier","1 cuillère à soupe bombée d'édulcorant granulé artificiel","1 cuillère à café rase de cannelle moulue","6 g de levure chimique","3 œufs","3 cuillères à soupe rases de lait écrémé","75 g de tartinade à base d'huile végétale, fondue","1 kg de pommes"],
["Préchauffez le four à 200 °C/thermostat 6.","Tamisez la farine dans un bol, ajoutez l'édulcorant artificiel, la levure chimique et la cannelle, et mélangez.","Creusez un puits au centre des ingrédients secs et ajoutez les œufs et le lait. Fouettez, puis ajoutez le beurre fondu.","Pelez et épépinez les pommes en retirant le cœur. Coupez-les en grosses tranches. Ajoutez les tranches de pomme au mélange et incorporez-les délicatement.","Graissez un moule à gâteau (d'environ 23 cm de diamètre) avec un peu d'huile végétale. Versez le mélange dans le moule et faites cuire au four 35 minutes.","Démoulez sur une grille de refroidissement. Laissez refroidir et servez."],
["Commencez par préparer la pâte afin de la laisser reposer pendant que vous pelez les pommes.","Vous pouvez aussi remplacer les pommes par des poires, et la cannelle par du gingembre moulu ou des épices mélangées."]),
R(7014156,"Cari de chou-fleur rôti, de paneer et de pois chiches",
"Un cari de légumes délicieusement savoureux avec du paneer et des pois chiches. Garni de chou-fleur rôti, épicé et croustillant.",
"4","504 g",
["2 cuillères à café d'huile","500 g de chou-fleur, en petits bouquets","2 cuillères à café de curcuma","2 oignons, hachés","1 grosse patate douce, en cubes (300 g)","1 poivron rouge, haché","3 gousses d'ail, écrasées","1 cuillère à café de cumin moulu","1 cuillère à soupe de pâte de cari moyen","1 cube de bouillon de légumes faible en sel, dissous dans 400 ml d'eau","100 g de paneer","240 g de pois chiches, égouttés","80 g de petits pois surgelés, décongelés","2 cuillères à soupe de yogourt à 0 % de matières grasses"],
["Préchauffez le four à 180 °C/thermostat 4 et huilez légèrement une plaque de cuisson avec 1 cuillère à café d'huile.","Rincez le chou-fleur à l'eau froide, secouez-le pour retirer l'excédent d'eau, puis mettez-le dans un bol. Saupoudrez de curcuma et mélangez bien. Placez sur la plaque de cuisson et faites rôtir 20 minutes, jusqu'à ce que les bords commencent à noircir, puis réservez.","Pendant ce temps, mettez 1 cuillère à café d'huile dans une casserole et ajoutez l'oignon. Faites cuire 3 à 4 minutes, jusqu'à ce qu'il soit ramolli, mais pas doré.","Ajoutez la patate douce, le poivron rouge, l'ail, le cumin et la pâte de cari, puis faites cuire encore 2 à 3 minutes en remuant régulièrement.","Versez le bouillon, mélangez bien, couvrez, puis laissez mijoter 8 à 10 minutes, jusqu'à ce que la patate douce soit presque tendre.","Ajoutez le paneer, les pois chiches et les petits pois, puis continuez à faire bouillir sans couvercle 5 à 6 minutes. Incorporez le yogourt et servez garni du chou-fleur rôti."],
["Essayez des haricots mélangés ou des haricots cannellini à la place des pois chiches.","Essayez d'ajouter d'autres légumes, comme 150 g d'épinards frais ou des champignons.","Vous pouvez utiliser le yogourt nature de votre choix, mais cela modifiera les valeurs nutritionnelles.","Instructions de congélation : peut être congelé une fois cuit. Décongelez au réfrigérateur ou au micro-ondes, puis réchauffez jusqu'à ce que ce soit bien chaud à cœur.",fv(4)]),
R(7014811,"Poulet à la marocaine",
"Servez ce plat avec du couscous pour un vrai régal nord-africain.",
"4","212 g",
["4 gros hauts de cuisse de poulet sans peau (100 g chacun)","4 bâtons de cannelle","2 gousses d'ail, écrasées","2 cuillères à café de paprika","1 cuillère à café de cumin","1 cuillère à soupe d'huile d'olive","2 carottes, hachées","150 g de haricots verts fins, coupés en deux","1 cuillère à café de curcuma","25 g d'olives vertes","75 g d'abricots secs prêts à manger","le zeste râpé et le jus de 1 citron","2 cuillères à soupe de menthe fraîche hachée, plus un peu pour garnir","200 ml de bouillon de poulet faible en sel","poivre noir fraîchement moulu"],
["Enroulez chaque haut de cuisse de poulet autour d'un bâton de cannelle.","Mélangez l'ail, le paprika, le cumin et la moitié de l'huile. Placez le poulet dans un plat non métallique, versez le mélange d'épices à la cuillère, enrobez bien, puis laissez mariner au moins 1 heure.","Faites chauffer le reste de l'huile dans une casserole, ajoutez les morceaux de poulet (toujours enroulés autour du bâton de cannelle) et faites-les dorer de tous les côtés. Retirez-les de la casserole à l'aide d'une écumoire et réservez.","Ajoutez la carotte et les haricots dans la casserole et faites cuire à feu doux environ 5 à 6 minutes. Incorporez le curcuma et ajoutez tous les ingrédients restants dans la casserole, avec le poulet.","Versez le bouillon, portez à ébullition, couvrez et laissez mijoter 12 à 15 minutes, jusqu'à ce que le poulet soit tendre.","Assaisonnez, garnissez de menthe et servez avec beaucoup de couscous cuit à la vapeur."],
["Si vous n'avez pas de bâtons de cannelle, ajoutez 1 cuillère à café de cannelle moulue à la marinade.","Pour une alternative sans gluten, servez avec du riz basmati parsemé de graines de grenade.","Instructions de congélation : peut être congelé une fois cuit. Décongelez ensuite au réfrigérateur ou au micro-ondes et réchauffez jusqu'à ce que ce soit bien chaud à cœur.",fv(1)]),
]
